python -c "
from glom import glom, Invoke

def add(x, y):
    print(f'x={x!r}, y={y!r}')
    return x + y

class DebugInvoke(Invoke):
    def glomit(self, target, scope):
        from glom.core import glom as _glom
        resolved_args = tuple(_glom(target, arg, scope) if isinstance(arg, tuple) else arg for arg in self.args)
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            print(f'k={k}, v={v!r}, isinstance(v,tuple)={isinstance(v, tuple)}')
            if isinstance(v, tuple):
                resolved_kwargs[k] = _glom(target, v, scope)
            else:
                resolved_kwargs[k] = v
        print(f'resolved_kwargs={resolved_kwargs}')
        return self.func(*resolved_args, **resolved_kwargs)

target = {'a': 1, 'b': 2}
result = glom(target, DebugInvoke(add, ('a',), {'y': ('b',)}))
print('Result:', result)
"
